server {
  listen 8080;
  server_name _;
  root /srv/repo;
  location / {
    autoindex on;
    autoindex_exact_size off;
  }
}

ui = true
listener "tcp" {
  tls_disable = 1
  address = "[::]:8200"
  cluster_address = "[::]:8201"
  telemetry {
    unauthenticated_metrics_access = "true"
  }
}
telemetry {
  prometheus_retention_time = "1m",
  disable_hostname = true
}
storage "raft" {
  path = "/vault/data"
}
service_registration "kubernetes" {}
